cd experiment3/model_loop; python3 -c "
import json,glob
for f in sorted(glob.glob('iter_*/critique/ppc_results.json')):
    d=json.load(open(f)); r=d.get('results',d)
    items = r.items() if isinstance(r,dict) else [(x.get('name'),x) for x in r]
    for k,v in items:
        if isinstance(v,dict): print(f[:6],k,round(v.get('t_observed',0),3),round(v.get('null_mean',0),3),round(v.get('p_value',1),3))
"; ls iter_4/critique/scratch; head -5 responses.csv

